using System.Net;using System.Net.Http.Json;using System.Text.Json;namespace RaceDay.Mvc.Services;public class RaceApi(HttpClient h,IHttpContextAccessor x,IConfiguration c){string Base=>c["Api:BaseUrl"]??"http://localhost:5080/";HttpRequestMessage Req(HttpMethod m,string p,object? body=null){var r=new HttpRequestMessage(m,new Uri(new Uri(Base),p));var cookie=x.HttpContext?.Session.GetString("apiCookie");if(cookie!=null)r.Headers.TryAddWithoutValidation("Cookie",cookie);if(body!=null)r.Content=JsonContent.Create(body);return r;}public async Task<T?> Get<T>(string p){using var r=Req(HttpMethod.Get,p);using var q=await h.SendAsync(r);if(!q.IsSuccessStatusCode)return default;return await q.Content.ReadFromJsonAsync<T>();}public async Task<(bool ok,string error)> Send(HttpMethod m,string p,object? b=null){using var r=Req(m,p,b);using var q=await h.SendAsync(r);if(q.IsSuccessStatusCode)return(true,"");try{var j=JsonDocument.Parse(await q.Content.ReadAsStringAsync());return(false,j.RootElement.TryGetProperty("message",out var v)?v.GetString()??"Request failed":"Request failed");}catch{return(false,"Request failed. Please check your details.");}}public async Task<(bool ok,string error)> Login(string email,string password){using var r=Req(HttpMethod.Post,"api/auth/login",new{email,password});using var q=await h.SendAsync(r);if(!q.IsSuccessStatusCode)return(false,"Email or password is incorrect.");if(q.Headers.TryGetValues("Set-Cookie",out var vals)){var ck=vals.FirstOrDefault()?.Split(';')[0];if(ck!=null)x.HttpContext!.Session.SetString("apiCookie",ck);}var u=await q.Content.ReadFromJsonAsync<User>();if(u==null)return(false,"Could not read account.");x.HttpContext!.Session.SetInt32("userId",u.UserId);x.HttpContext.Session.SetString("role",u.Role);x.HttpContext.Session.SetString("name",u.FirstName+" "+u.LastName);return(true,"");}public async Task<(bool ok,string error)> Upload(string p,IFormFile f){using var r=Req(HttpMethod.Post,p);var form=new MultipartFormDataContent();form.Add(new StreamContent(f.OpenReadStream()),"file",Path.GetFileName(f.FileName));r.Content=form;using var q=await h.SendAsync(r);return(q.IsSuccessStatusCode,q.IsSuccessStatusCode?"":"Image upload failed. Verify API Blob Storage configuration.");}}public record User(int UserId,string FirstName,string LastName,string Email,string Role,string? PhoneNumber,DateTime CreatedAt);public record RaceEvent(int EventId,int OrganiserId,string EventName,string? Description,DateTime EventDate,string Venue,string City,string Province,string EventType,string Status,DateTime CreatedAt,string? BannerImageUrl);public record Category(int CategoryId,int EventId,string CategoryName,decimal DistanceKm,decimal EntryFee,int? MaximumParticipants);public record Enrolment(int EnrolmentId,int ParticipantId,int CategoryId,string CategoryName,int EventId,string EventName,DateTime EnrolmentDate,string? EmergencyContactName,string? EmergencyContactPhone,string PaymentStatus,string EnrolmentStatus);public record RaceResult(int ResultId,int EnrolmentId,int ParticipantId,string ParticipantName,int EventId,string EventName,int? FinishPosition,int? FinishTimeSeconds,string ResultStatus,DateTime RecordedAt);public record EventDetails(RaceEvent Event,List<Category> Categories,List<object> Routes);